def load_torchvision_fpn(
            model: torch.nn.Module,
            params: Dict,
            p2: bool = True,
            p6p7: bool = False) -> None:
    """Loads Torchvision's fpn parameters into a `FPN` class."""

    with torch.no_grad():
        if p2:
            model.layer4.conv_in.weight.copy_(params["backbone.fpn.inner_blocks.3.weight"])
            model.layer4.conv_in.bias.copy_(params["backbone.fpn.inner_blocks.3.bias"])
            model.layer4.conv_out.weight.copy_(params["backbone.fpn.layer_blocks.3.weight"])
            model.layer4.conv_out.bias.copy_(params["backbone.fpn.layer_blocks.3.bias"])
        model.layer3.conv_in.weight.copy_(params["backbone.fpn.inner_blocks.2.weight"])
        model.layer3.conv_in.bias.copy_(params["backbone.fpn.inner_blocks.2.bias"])
        model.layer3.conv_out.weight.copy_(params["backbone.fpn.layer_blocks.2.weight"])
        model.layer3.conv_out.bias.copy_(params["backbone.fpn.layer_blocks.2.bias"])
        model.layer2.conv_in.weight.copy_(params["backbone.fpn.inner_blocks.1.weight"])
        model.layer2.conv_in.bias.copy_(params["backbone.fpn.inner_blocks.1.bias"])
        model.layer2.conv_out.weight.copy_(params["backbone.fpn.layer_blocks.1.weight"])
        model.layer2.conv_out.bias.copy_(params["backbone.fpn.layer_blocks.1.bias"])
        model.layer1.conv_in.weight.copy_(params["backbone.fpn.inner_blocks.0.weight"])
        model.layer1.conv_in.bias.copy_(params["backbone.fpn.inner_blocks.0.bias"])
        model.layer1.conv_out.weight.copy_(params["backbone.fpn.layer_blocks.0.weight"])
        model.layer1.conv_out.bias.copy_(params["backbone.fpn.layer_blocks.0.bias"])
        if p6p7:
            model.conv_p6.weight.copy_(params["backbone.fpn.extra_blocks.p6.weight"])
            model.conv_p6.bias.copy_(params["backbone.fpn.extra_blocks.p6.bias"])
            model.conv_p7.weight.copy_(params["backbone.fpn.extra_blocks.p7.weight"])
            model.conv_p7.bias.copy_(params["backbone.fpn.extra_blocks.p7.bias"])

def load_torchvision_fasterrcnn(model: torch.nn.Module, model_file: str) -> None:
    """Loads Torchvision's `fasterrcnn_resnet50_fpn` parameters into a `FasterRCNN` class."""

    params = torch.load(model_file, map_location="cpu")
    load_torchvision_resnet(model.resnet, params=params)
    load_torchvision_fpn(model.fpn, params)
    with torch.no_grad():
        model.rpn.conv.weight.copy_(params["rpn.head.conv.weight"])
        model.rpn.conv.bias.copy_(params["rpn.head.conv.bias"])
        model.rpn.reg_bbox.weight.copy_(params["rpn.head.bbox_pred.weight"])
        model.rpn.reg_bbox.bias.copy_(params["rpn.head.bbox_pred.bias"])
        model.rpn.cls_logits.weight.copy_(params["rpn.head.cls_logits.weight"])
        model.rpn.cls_logits.bias.copy_(params["rpn.head.cls_logits.bias"])
        model.detector.hidden.fc1.weight.copy_(params["roi_heads.box_head.fc6.weight"])
        model.detector.hidden.fc1.bias.copy_(params["roi_heads.box_head.fc6.bias"])
        model.detector.hidden.fc2.weight.copy_(params["roi_heads.box_head.fc7.weight"])
        model.detector.hidden.fc2.bias.copy_(params["roi_heads.box_head.fc7.bias"])
        model.detector.reg_bbox.weight.copy_(params["roi_heads.box_predictor.bbox_pred.weight"])
        model.detector.reg_bbox.bias.copy_(params["roi_heads.box_predictor.bbox_pred.bias"])
        model.detector.cls_logits.weight.copy_(params["roi_heads.box_predictor.cls_score.weight"])
        model.detector.cls_logits.bias.copy_(params["roi_heads.box_predictor.cls_score.bias"])

def load_torchvision_fcos(model: torch.nn.Module, model_file: str, load_final_conv_layer: bool = True) -> None:
    """Loads Torchvision's `fcos_resnet50_fpn` parameters into a `FCOS` class."""

    params = torch.load(model_file, map_location="cpu")
    load_torchvision_resnet(model.resnet, params=params)
    load_torchvision_fpn(model.fpn, params, False, True)
    with torch.no_grad():
        model.cls_subnet.layer1.conv.weight.copy_(params["head.classification_head.conv.0.weight"])
        model.cls_subnet.layer1.conv.bias.copy_(params["head.classification_head.conv.0.bias"])
        model.cls_subnet.layer1.gn.weight.copy_(params["head.classification_head.conv.1.weight"])
        model.cls_subnet.layer1.gn.bias.copy_(params["head.classification_head.conv.1.bias"])
        model.cls_subnet.layer2.conv.weight.copy_(params["head.classification_head.conv.3.weight"])
